#!/usr/bin/env python3
"""One-shot installer for the Security Evaluation Framework.

Usage (from your backend/ directory):
    python setup_security_eval.py
Creates backend/tests/security_eval/ with the dataset, Semgrep rules, harness and all tests,
then builds the manifest. Existing files are NOT overwritten unless you pass --force.
"""
import json
import subprocess
import sys
from pathlib import Path

FILES = json.loads(r'''{
 "security_eval/README.md": "# Security Evaluation Framework\n\nMeasures whether the platform finds real vulnerabilities and leaves secure code alone, using **actual** Bandit and\nSemgrep output. Uploaded/sample code is never imported or executed; scans run on an isolated temp copy.\n\n## Layout (place under `backend/tests/security_eval/`; ensure `backend/tests/__init__.py` exists)\n- `dataset/python/{vulnerable,secure}/*.py` – paired samples for 10 categories. Ground truth = inline `# VULN[category:Severity]` markers.\n- `dataset/manifest.json` – generated from the markers (`build_manifest.py`), so line numbers cannot drift.\n- `rules/semgrep/python-security.yml` – local rules (no network). Covers gaps Bandit cannot (XSS, path traversal, auth, validation, password storage).\n- `scanners.py`, `normalize.py`, `metrics.py`, `report.py`, `run_evaluation.py` – the harness.\n- `app_adapter.py` – the only file coupling tests to your app (routes, field names, patch targets).\n- `import_owasp_benchmark.py` – curated OWASP Benchmark subset importer (Java, later).\n\n## Install and run\n```bash\ncd backend\npip install -r tests/security_eval/requirements-dev.txt\npython -m tests.security_eval.build_manifest            # regenerate manifest\npython -m tests.security_eval.run_evaluation            # metrics report -> tests/security_eval/results/report.{md,json}\npython -m pytest tests/security_eval -v                 # full automated suite (writes the same report)\n```\nApp/AI/Hindsight tests (skipped unless configured):\n```bash\nexport EVAL_APP_IMPORT=app.main:app          # in-process FastAPI (enables failure injection), or EVAL_API_URL=http://127.0.0.1:8000\nexport HINDSIGHT_URL=http://localhost:8888\nexport EVAL_HINDSIGHT_RESTART_CMD=\"docker restart hindsight\"   # optional real restart test\nexport EVAL_AI_LIVE=1                        # optional: re-scan AI fixes with a real provider\npython -m pytest tests/security_eval -v\n```\nThresholds/tuning env vars: `EVAL_MIN_PRECISION`, `EVAL_MIN_RECALL`, `EVAL_LINE_TOLERANCE`, `EVAL_SCANNER_TIMEOUT`, `EVAL_MAX_UPLOAD_BYTES`.\n\n## Metric rules\nTP = labeled vulnerability matched by file + accepted category + line (±tolerance). Duplicate findings count once.\nFP = non-informational finding in a secure file, or a target-category finding in a vulnerable file matching no label.\nFN = labeled vulnerability with no match. Other-category findings in vulnerable files are listed as \"unlabeled\" for triage.\nImport-presence Bandit rules (B401–B415) plus B101/B603/B607 are excluded. If any scanner times out or is missing, the report says INCOMPLETE.\n\n## Caveats\n- The custom Semgrep rules and the samples were written together, so Semgrep results on this dataset are optimistic. Use OWASP Benchmark/Juliet and held-out samples for an independent view.\n- WebGoat has no per-line ground truth: use it as a manual demo target, not a metrics source.\n- Java/JavaScript: dataset folders and scanner registry exist; add Semgrep rules (and an ESLint adapter) before enabling.\n",
 "security_eval/__init__.py": "",
 "security_eval/app_adapter.py": "\"\"\"The ONLY file that couples this framework to your application. Edit the constants to match your routes.\n\nAssumed contract (adjust ENDPOINTS / FIELDS if your Modules 5-7 differ):\n  POST ENDPOINTS[\"scan\"]  multipart field \"files\"  -> JSON {\"id\": ..., \"findings\": [ {id,file,line_start,category,severity,tool,...} ]}\n  POST ENDPOINTS[\"explain\"|\"fix\"|\"feedback\"].format(id=finding_id)\nRun modes: in-process via EVAL_APP_IMPORT=\"app.main:app\" (FastAPI TestClient, allows failure injection),\nor against a running server via EVAL_API_URL=\"http://127.0.0.1:8000\".\n\"\"\"\nfrom __future__ import annotations\n\nimport importlib\nimport os\n\nAPI_URL = os.getenv(\"EVAL_API_URL\")\nAPP_IMPORT = os.getenv(\"EVAL_APP_IMPORT\")  # e.g. \"app.main:app\"\nENDPOINTS = {\n    \"scan\": \"/api/scans\",\n    \"explain\": \"/api/findings/{id}/explain\",\n    \"fix\": \"/api/findings/{id}/fix\",\n    \"feedback\": \"/api/findings/{id}/feedback\",\n}\nFIELDS = {\"findings\": \"findings\", \"file\": \"file\", \"line\": \"line_start\", \"category\": \"category\", \"severity\": \"severity\", \"id\": \"id\"}\nMAX_UPLOAD_BYTES = int(os.getenv(\"EVAL_MAX_UPLOAD_BYTES\", str(1_000_000)))  # your configured limit\n\n# dotted \"module:attr\" targets patched for failure injection / recording\nAI_PROVIDER_FACTORY = os.getenv(\"EVAL_AI_FACTORY\", \"app.services.ai.factory:get_provider\")\nMEMORY_CLIENT_FACTORY = os.getenv(\"EVAL_MEMORY_FACTORY\", \"app.services.memory:get_memory_client\")\n\nHINDSIGHT_URL = os.getenv(\"HINDSIGHT_URL\")  # e.g. http://localhost:8888\n\n\ndef load(target: str):\n    module, attr = target.split(\":\")\n    return getattr(importlib.import_module(module), attr)\n\n\ndef make_client():\n    if APP_IMPORT:\n        from fastapi.testclient import TestClient\n        return TestClient(load(APP_IMPORT))\n    if API_URL:\n        import httpx\n        return httpx.Client(base_url=API_URL, timeout=120)\n    return None\n\n\ndef upload(client, name: str, content: bytes, mime: str = \"text/x-python\"):\n    return client.post(ENDPOINTS[\"scan\"], files=[(\"files\", (name, content, mime))])\n\n\ndef findings_of(response) -> list[dict]:\n    return response.json().get(FIELDS[\"findings\"], [])\n",
 "security_eval/build_manifest.py": "\"\"\"Build dataset/manifest.json from inline `# VULN[category:Severity]` markers.\n\nGround truth lives next to the code it describes, so line numbers cannot drift.\nRun:  python -m tests.security_eval.build_manifest\n\"\"\"\nfrom __future__ import annotations\n\nimport hashlib\nimport json\nimport re\nfrom pathlib import Path\n\nfrom . import config\n\nMARKER = re.compile(r\"#\\s*VULN\\[(?P<cat>[a-z_]+):(?P<sev>Critical|High|Medium|Low)\\]\")\n\n\ndef build() -> dict:\n    samples = []\n    for path in sorted(config.DATASET_DIR.glob(\"python/*/*.py\")):\n        rel = path.relative_to(config.DATASET_DIR).as_posix()\n        split = path.parent.name\n        text = path.read_text(encoding=\"utf-8\")\n        expected = []\n        for lineno, line in enumerate(text.splitlines(), start=1):\n            m = MARKER.search(line)\n            if m:\n                expected.append({\"category\": m[\"cat\"], \"severity\": m[\"sev\"], \"line\": lineno,\n                                 \"cwe\": config.CATEGORY_CWE.get(m[\"cat\"], \"\")})\n        samples.append({\n            \"id\": f\"py-{split}-{path.stem}\", \"language\": \"python\", \"file\": rel, \"split\": split,\n            \"source\": \"original-controlled\", \"sha256\": hashlib.sha256(text.encode()).hexdigest(),\n            \"expected\": expected,\n        })\n    for fragment in sorted(config.DATASET_DIR.glob(\"*/*/manifest.fragment.json\")):  # e.g. OWASP Benchmark import\n        samples.extend(json.loads(fragment.read_text(encoding=\"utf-8\"))[\"samples\"])\n    return {\"version\": 1, \"categories\": config.CATEGORIES, \"samples\": samples}\n\n\nif __name__ == \"__main__\":\n    manifest = build()\n    config.MANIFEST_PATH.write_text(json.dumps(manifest, indent=2) + \"\\n\", encoding=\"utf-8\")\n    n_exp = sum(len(s[\"expected\"]) for s in manifest[\"samples\"])\n    print(f\"Wrote {config.MANIFEST_PATH} ({len(manifest['samples'])} samples, {n_exp} expected vulnerabilities)\")\n",
 "security_eval/config.py": "\"\"\"Central configuration for the security evaluation framework.\"\"\"\nfrom __future__ import annotations\n\nimport os\nfrom pathlib import Path\n\nROOT = Path(__file__).resolve().parent\nDATASET_DIR = ROOT / \"dataset\"\nRULES_DIR = ROOT / \"rules\" / \"semgrep\"\nRESULTS_DIR = ROOT / \"results\"\nMANIFEST_PATH = DATASET_DIR / \"manifest.json\"\n\n# A finding matches an expected vulnerability when it is in the same file, an accepted\n# category, and within this many lines (None-line expectations are file-level).\nLINE_TOLERANCE = int(os.getenv(\"EVAL_LINE_TOLERANCE\", \"2\"))\nSCANNER_TIMEOUT = float(os.getenv(\"EVAL_SCANNER_TIMEOUT\", \"300\"))\nLARGE_FILE_MAX_SECONDS = float(os.getenv(\"EVAL_LARGE_FILE_MAX_SECONDS\", \"180\"))\nMIN_PRECISION = float(os.getenv(\"EVAL_MIN_PRECISION\", \"0.80\"))\nMIN_RECALL = float(os.getenv(\"EVAL_MIN_RECALL\", \"0.80\"))\n\nSEVERITY_RANK = {\"Low\": 1, \"Medium\": 2, \"High\": 3, \"Critical\": 4}\n\nCATEGORIES = [\n    \"sql_injection\", \"xss\", \"command_injection\", \"hardcoded_credentials\",\n    \"insecure_password_storage\", \"weak_crypto\", \"path_traversal\",\n    \"insecure_deserialization\", \"missing_input_validation\", \"insecure_authentication\",\n]\n\nCATEGORY_CWE = {\n    \"sql_injection\": \"CWE-89\", \"xss\": \"CWE-79\", \"command_injection\": \"CWE-78\",\n    \"hardcoded_credentials\": \"CWE-798\", \"insecure_password_storage\": \"CWE-916\",\n    \"weak_crypto\": \"CWE-327\", \"path_traversal\": \"CWE-22\",\n    \"insecure_deserialization\": \"CWE-502\", \"missing_input_validation\": \"CWE-20\",\n    \"insecure_authentication\": \"CWE-287\",\n}\n\n# expected category -> finding categories accepted as a correct detection.\nACCEPTED_CATEGORIES = {c: {c} for c in CATEGORIES}\nACCEPTED_CATEGORIES[\"insecure_password_storage\"] = {\"insecure_password_storage\", \"weak_crypto\"}\n\n# Bandit HIGH severity findings in these categories are reported as Critical.\n# Keep this in sync with the application's own severity mapping.\nCRITICAL_ELIGIBLE = {\"sql_injection\", \"command_injection\", \"insecure_deserialization\"}\n\n# language -> scanners. \"implemented\" scanners run today; others report status \"not_implemented\".\nLANGUAGES = {\n    \"python\": {\"extensions\": [\".py\"], \"scanners\": [\"bandit\", \"semgrep\"]},\n    \"java\": {\"extensions\": [\".java\"], \"scanners\": [\"semgrep\"]},\n    \"javascript\": {\"extensions\": [\".js\", \".jsx\", \".ts\", \".tsx\"], \"scanners\": [\"semgrep\", \"eslint\"]},\n}\nIMPLEMENTED_SCANNERS = {\"bandit\", \"semgrep\"}\n",
 "security_eval/conftest.py": "from __future__ import annotations\n\nimport json\nimport pytest\n\nfrom tests.security_eval import build_manifest, config, metrics, report, scanners\n\n_STATE: dict = {\"perf\": {}}\n\n\ndef record_perf(name: str, seconds: float, note: str = \"\") -> None:\n    _STATE[\"perf\"][name] = {\"seconds\": seconds, \"note\": note}\n\n\n@pytest.fixture(scope=\"session\")\ndef manifest() -> dict:\n    config.MANIFEST_PATH.write_text(json.dumps(build_manifest.build(), indent=2) + \"\\n\", encoding=\"utf-8\")\n    data = json.loads(config.MANIFEST_PATH.read_text(encoding=\"utf-8\"))\n    data[\"samples\"] = [s for s in data[\"samples\"] if s[\"language\"] == \"python\"]\n    return data\n\n\n@pytest.fixture(scope=\"session\")\ndef scan_result(manifest):\n    result = scanners.scan_dataset(manifest, \"python\")\n    if not result.complete:\n        pytest.fail(\"Scanners did not complete, refusing to report results: \"\n                    + \"; \".join(f\"{r.tool}={r.status} {r.error}\" for r in result.runs if r.status != \"ok\"))\n    _STATE.update(manifest=manifest, scan=result)\n    return result\n\n\n@pytest.fixture(scope=\"session\")\ndef evaluation(manifest, scan_result):\n    ev = metrics.evaluate(manifest, scan_result.findings)\n    _STATE[\"ev\"] = ev\n    return ev\n\n\n@pytest.fixture\ndef perf():\n    return record_perf\n\n\ndef pytest_sessionfinish(session, exitstatus):\n    if all(k in _STATE for k in (\"manifest\", \"scan\", \"ev\")):\n        report.write_report(_STATE[\"manifest\"], _STATE[\"scan\"], _STATE[\"ev\"], _STATE[\"perf\"])\n        (config.RESULTS_DIR / \"performance.json\").write_text(json.dumps(_STATE[\"perf\"], indent=2))\n",
 "security_eval/dataset/python/secure/command_injection.py": "\"\"\"Secure sample: validated input, argument list, no shell.\"\"\"\nimport ipaddress\nimport subprocess\n\n\ndef ping(host):\n    address = ipaddress.ip_address(host)\n    subprocess.run([\"ping\", \"-c\", \"1\", str(address)], check=True, timeout=5)\n\n\ndef archive(path):\n    subprocess.run([\"tar\", \"czf\", \"backup.tgz\", \"--\", path], check=True, timeout=60)\n",
 "security_eval/dataset/python/secure/hardcoded_credentials.py": "\"\"\"Secure sample: secrets come from the environment.\"\"\"\nimport os\n\nDB_PASSWORD = os.environ[\"DB_PASSWORD\"]\nAPI_KEY = os.environ.get(\"API_KEY\", \"\")\n\n\ndef connect(make_conn):\n    return make_conn(host=os.environ[\"DB_HOST\"], user=os.environ[\"DB_USER\"], password=DB_PASSWORD)\n",
 "security_eval/dataset/python/secure/insecure_authentication.py": "\"\"\"Secure sample: verified JWTs and constant-time hash comparison.\"\"\"\nimport hmac\nimport os\n\nimport jwt\n\nSECRET = os.environ[\"JWT_SECRET\"]\n\n\ndef read_token(token):\n    return jwt.decode(token, SECRET, algorithms=[\"HS256\"])\n\n\ndef check_login(user, password_hash):\n    return hmac.compare_digest(user.password_hash, password_hash)\n",
 "security_eval/dataset/python/secure/insecure_deserialization.py": "\"\"\"Secure sample: data-only formats.\"\"\"\nimport json\n\nimport yaml\n\n\ndef load_session(blob):\n    return json.loads(blob)\n\n\ndef load_config(text):\n    return yaml.safe_load(text)\n",
 "security_eval/dataset/python/secure/insecure_password_storage.py": "\"\"\"Secure sample: salted, memory-hard KDF with constant-time comparison.\"\"\"\nimport hashlib\nimport hmac\nimport os\n\n\ndef hash_password(password: str) -> str:\n    salt = os.urandom(16)\n    digest = hashlib.scrypt(password.encode(), salt=salt, n=2**14, r=8, p=1)\n    return salt.hex() + \":\" + digest.hex()\n\n\ndef verify_password(password: str, stored: str) -> bool:\n    salt_hex, digest_hex = stored.split(\":\")\n    candidate = hashlib.scrypt(password.encode(), salt=bytes.fromhex(salt_hex), n=2**14, r=8, p=1)\n    return hmac.compare_digest(candidate.hex(), digest_hex)\n",
 "security_eval/dataset/python/secure/missing_input_validation.py": "\"\"\"Secure sample: allowlist validation before redirect / outbound request.\"\"\"\nimport requests\nfrom flask import Flask, abort, redirect, request, url_for\n\napp = Flask(__name__)\nALLOWED_TARGETS = {\"home\": \"home\", \"profile\": \"profile\"}\nALLOWED_FEEDS = {\"news\": \"https://feeds.example.com/news\"}\n\n\ndef validate_target(target):\n    if target not in ALLOWED_TARGETS:\n        abort(400)\n    return ALLOWED_TARGETS[target]\n\n\ndef validate_feed(name):\n    if name not in ALLOWED_FEEDS:\n        abort(400)\n    return ALLOWED_FEEDS[name]\n\n\n@app.route(\"/go\")\ndef go():\n    target = validate_target(request.args.get(\"next\", \"\"))\n    return redirect(url_for(target))\n\n\n@app.route(\"/fetch\")\ndef fetch():\n    feed = validate_feed(request.args.get(\"feed\", \"\"))\n    return requests.get(feed, timeout=5).text\n",
 "security_eval/dataset/python/secure/path_traversal.py": "\"\"\"Secure sample: filenames sanitized before touching the filesystem.\"\"\"\nimport os\n\nfrom flask import Flask, abort, request, send_file\nfrom werkzeug.utils import secure_filename\n\napp = Flask(__name__)\nBASE = \"/srv/files\"\n\n\n@app.route(\"/download\")\ndef download():\n    filename = secure_filename(request.args.get(\"file\", \"\"))\n    if not filename:\n        abort(400)\n    return send_file(os.path.join(BASE, filename))\n",
 "security_eval/dataset/python/secure/sql_injection.py": "\"\"\"Secure sample: parameterized queries.\"\"\"\n\n\ndef get_user(conn, username):\n    cur = conn.cursor()\n    cur.execute(\"SELECT * FROM users WHERE name = ?\", (username,))\n    return cur.fetchone()\n\n\ndef search_orders(conn, term):\n    cur = conn.cursor()\n    cur.execute(\"SELECT * FROM orders WHERE item LIKE ?\", (f\"%{term}%\",))\n    return cur.fetchall()\n",
 "security_eval/dataset/python/secure/weak_crypto.py": "\"\"\"Secure sample: SHA-256, AES-GCM, and md5 explicitly marked as non-security use.\"\"\"\nimport hashlib\nimport os\n\nfrom cryptography.hazmat.primitives.ciphers.aead import AESGCM\n\n\ndef checksum(data):\n    return hashlib.sha256(data).hexdigest()\n\n\ndef cache_key(data):\n    return hashlib.md5(data, usedforsecurity=False).hexdigest()\n\n\ndef encrypt(key, data):\n    nonce = os.urandom(12)\n    return nonce + AESGCM(key).encrypt(nonce, data, None)\n",
 "security_eval/dataset/python/secure/xss.py": "\"\"\"Secure sample: auto-escaped template rendering.\"\"\"\nfrom flask import Flask, request, render_template_string\nfrom markupsafe import escape\n\napp = Flask(__name__)\n\n\n@app.route(\"/greet\")\ndef greet():\n    name = request.args.get(\"name\", \"\")\n    return render_template_string(\"<h1>Hello {{ name }}</h1>\", name=name)\n\n\n@app.route(\"/banner\")\ndef banner():\n    msg = escape(request.args.get(\"msg\", \"\"))\n    return render_template_string(\"<div>{{ msg }}</div>\", msg=msg)\n",
 "security_eval/dataset/python/vulnerable/command_injection.py": "\"\"\"Vulnerable sample: OS command injection (CWE-78). Never executed.\"\"\"\nimport os\nimport subprocess\n\n\ndef ping(host):\n    os.system(\"ping -c 1 \" + host)  # VULN[command_injection:Critical]\n\n\ndef archive(path):\n    subprocess.call(\"tar czf backup.tgz \" + path, shell=True)  # VULN[command_injection:Critical]\n",
 "security_eval/dataset/python/vulnerable/hardcoded_credentials.py": "\"\"\"Vulnerable sample: hardcoded secrets (CWE-798). Values are fake.\"\"\"\nDB_PASSWORD = \"SuperSecret123!\"  # VULN[hardcoded_credentials:High]\nAPI_KEY = \"sk_live_51H8xYzAbCdEfGhIjKlMn\"  # VULN[hardcoded_credentials:High]\nAWS_ACCESS_KEY_ID = \"AKIAIOSFODNN7EXAMPLE\"  # VULN[hardcoded_credentials:Critical]\n\n\ndef connect(make_conn):\n    return make_conn(host=\"db.internal\", user=\"admin\", password=\"admin123\")  # VULN[hardcoded_credentials:High]\n",
 "security_eval/dataset/python/vulnerable/insecure_authentication.py": "\"\"\"Vulnerable sample: broken authentication patterns (CWE-287/CWE-347/CWE-256).\"\"\"\nimport jwt\n\n\ndef read_token(token):\n    return jwt.decode(token, options={\"verify_signature\": False})  # VULN[insecure_authentication:Critical]\n\n\ndef check_login(user, password):\n    if user.password == password:  # VULN[insecure_authentication:High]\n        return True\n    return False\n",
 "security_eval/dataset/python/vulnerable/insecure_deserialization.py": "\"\"\"Vulnerable sample: untrusted deserialization (CWE-502). Never executed.\"\"\"\nimport pickle\n\nimport yaml\n\n\ndef load_session(blob):\n    return pickle.loads(blob)  # VULN[insecure_deserialization:Critical]\n\n\ndef load_config(text):\n    return yaml.load(text)  # VULN[insecure_deserialization:High]\n",
 "security_eval/dataset/python/vulnerable/insecure_password_storage.py": "\"\"\"Vulnerable sample: fast unsalted hashes for passwords (CWE-916/CWE-328).\"\"\"\nimport hashlib\n\n\ndef hash_password(password):\n    return hashlib.md5(password.encode()).hexdigest()  # VULN[insecure_password_storage:High]\n\n\ndef store_user(db, username, password):\n    digest = hashlib.sha256(password.encode()).hexdigest()  # VULN[insecure_password_storage:High]\n    db[username] = digest\n",
 "security_eval/dataset/python/vulnerable/missing_input_validation.py": "\"\"\"Vulnerable sample: unvalidated user input reaches redirect/HTTP sinks (CWE-601/CWE-918).\"\"\"\nimport requests\nfrom flask import Flask, redirect, request\n\napp = Flask(__name__)\n\n\n@app.route(\"/go\")\ndef go():\n    target = request.args.get(\"next\")\n    return redirect(target)  # VULN[missing_input_validation:Medium]\n\n\n@app.route(\"/fetch\")\ndef fetch():\n    url = request.args.get(\"url\")\n    return requests.get(url, timeout=5).text  # VULN[missing_input_validation:High]\n",
 "security_eval/dataset/python/vulnerable/path_traversal.py": "\"\"\"Vulnerable sample: user-controlled file paths (CWE-22). Never executed.\"\"\"\nimport os\n\nfrom flask import Flask, request, send_file\n\napp = Flask(__name__)\nBASE = \"/srv/files\"\n\n\n@app.route(\"/download\")\ndef download():\n    filename = request.args.get(\"file\")\n    return send_file(BASE + \"/\" + filename)  # VULN[path_traversal:High]\n\n\n@app.route(\"/read\")\ndef read():\n    name = request.args.get(\"name\")\n    with open(os.path.join(BASE, name)) as handle:  # VULN[path_traversal:High]\n        return handle.read()\n",
 "security_eval/dataset/python/vulnerable/sql_injection.py": "\"\"\"Vulnerable sample: SQL injection via string-built queries (CWE-89). Never executed.\"\"\"\n\n\ndef get_user(conn, username):\n    cur = conn.cursor()\n    cur.execute(\"SELECT * FROM users WHERE name = '\" + username + \"'\")  # VULN[sql_injection:Critical]\n    return cur.fetchone()\n\n\ndef search_orders(conn, term):\n    cur = conn.cursor()\n    query = f\"SELECT * FROM orders WHERE item LIKE '%{term}%'\"  # VULN[sql_injection:Critical]\n    cur.execute(query)\n    return cur.fetchall()\n",
 "security_eval/dataset/python/vulnerable/weak_crypto.py": "\"\"\"Vulnerable sample: broken hashes and ciphers (CWE-327/CWE-328).\"\"\"\nimport hashlib\n\nfrom Crypto.Cipher import DES\n\n\ndef checksum(data):\n    return hashlib.md5(data).hexdigest()  # VULN[weak_crypto:Medium]\n\n\ndef sign(data):\n    return hashlib.sha1(data).hexdigest()  # VULN[weak_crypto:Medium]\n\n\ndef encrypt(key, data):\n    cipher = DES.new(key, DES.MODE_ECB)  # VULN[weak_crypto:High]\n    return cipher.encrypt(data)\n",
 "security_eval/dataset/python/vulnerable/xss.py": "\"\"\"Vulnerable sample: reflected XSS in Flask handlers (CWE-79). Never executed.\"\"\"\nfrom flask import Flask, request, render_template_string\nfrom markupsafe import Markup\n\napp = Flask(__name__)\n\n\n@app.route(\"/greet\")\ndef greet():\n    name = request.args.get(\"name\", \"\")\n    return f\"<h1>Hello {name}</h1>\"  # VULN[xss:High]\n\n\n@app.route(\"/banner\")\ndef banner():\n    msg = request.args.get(\"msg\", \"\")\n    return render_template_string(\"<div>\" + msg + \"</div>\")  # VULN[xss:High]\n\n\n@app.route(\"/note\")\ndef note():\n    text = request.args.get(\"text\", \"\")\n    return Markup(\"<p>\" + text + \"</p>\")  # VULN[xss:High]\n",
 "security_eval/import_owasp_benchmark.py": "\"\"\"Import a small, balanced, curated subset of the OWASP Benchmark (Java) from a LOCAL clone.\n\n    git clone https://github.com/OWASP-Benchmark/BenchmarkJava ~/BenchmarkJava\n    python -m tests.security_eval.import_owasp_benchmark --repo ~/BenchmarkJava --per-category 5\n\nOnly the selected test-case files are copied (never the whole repo). Ground truth is file-level (the Benchmark's\nexpectedresults CSV has no line numbers), so entries use line=null. Check the Benchmark's license (GPL-2.0) before\nredistributing the copied files; keep ATTRIBUTION.md with them. Java detection needs Semgrep Java rules in\nrules/semgrep/ (not included). NIST Juliet covers Java and C/C++, not Python: import it the same way when Java is enabled.\n\"\"\"\nfrom __future__ import annotations\n\nimport argparse\nimport csv\nimport json\nimport shutil\nfrom pathlib import Path\n\nfrom . import config\n\nCATEGORY_MAP = {\"sqli\": \"sql_injection\", \"xss\": \"xss\", \"cmdi\": \"command_injection\",\n                \"pathtraver\": \"path_traversal\", \"crypto\": \"weak_crypto\", \"hash\": \"weak_crypto\"}\nDEFAULT_SEVERITY = {\"sql_injection\": \"Critical\", \"command_injection\": \"Critical\", \"xss\": \"High\",\n                    \"path_traversal\": \"High\", \"weak_crypto\": \"Medium\"}\n\n\ndef main() -> None:\n    ap = argparse.ArgumentParser()\n    ap.add_argument(\"--repo\", required=True, type=Path)\n    ap.add_argument(\"--per-category\", type=int, default=5, help=\"N vulnerable + N safe cases per category\")\n    args = ap.parse_args()\n\n    csv_path = next(args.repo.glob(\"expectedresults-*.csv\"))\n    testcode = args.repo / \"src/main/java/org/owasp/benchmark/testcode\"\n    out = config.DATASET_DIR / \"java\" / \"owasp_benchmark\"\n    out.mkdir(parents=True, exist_ok=True)\n\n    buckets: dict[tuple[str, bool], list[tuple[str, str]]] = {}\n    with csv_path.open() as fh:\n        for row in csv.reader(fh):\n            if not row or row[0].startswith(\"#\") or row[1] not in CATEGORY_MAP:\n                continue\n            buckets.setdefault((CATEGORY_MAP[row[1]], row[2].strip() == \"true\"), []).append((row[0], row[3]))\n\n    samples = []\n    for (cat, vulnerable), rows in sorted(buckets.items()):\n        for name, cwe in sorted(rows)[: args.per_category]:\n            shutil.copyfile(testcode / f\"{name}.java\", out / f\"{name}.java\")\n            samples.append({\n                \"id\": f\"owasp-{name}\", \"language\": \"java\", \"file\": f\"java/owasp_benchmark/{name}.java\",\n                \"split\": \"vulnerable\" if vulnerable else \"secure\", \"source\": \"OWASP Benchmark v1.2\",\n                \"expected\": [{\"category\": cat, \"severity\": DEFAULT_SEVERITY[cat], \"line\": None, \"cwe\": f\"CWE-{cwe}\"}] if vulnerable else [],\n            })\n    (out / \"manifest.fragment.json\").write_text(json.dumps({\"samples\": samples}, indent=2))\n    (out / \"ATTRIBUTION.md\").write_text(\"Selected test cases from the OWASP Benchmark Project \"\n                                        \"(https://owasp.org/www-project-benchmark/), GPL-2.0. Ground truth: expectedresults CSV.\\n\")\n    print(f\"Imported {len(samples)} Benchmark cases into {out}\")\n\n\nif __name__ == \"__main__\":\n    main()\n",
 "security_eval/metrics.py": "\"\"\"Compute detection metrics from real scanner findings versus manifest ground truth.\"\"\"\nfrom __future__ import annotations\n\nfrom collections import defaultdict\n\nfrom . import config\nfrom .models import Finding\n\n\ndef matches(expected: dict, finding: Finding) -> bool:\n    if finding.file != expected[\"file\"]:\n        return False\n    if expected.get(\"line\") is not None and abs(finding.line - expected[\"line\"]) > config.LINE_TOLERANCE:\n        return False\n    accepted = config.ACCEPTED_CATEGORIES.get(expected[\"category\"], {expected[\"category\"]})\n    return finding.category in accepted\n\n\ndef _div(a: float, b: float):\n    return None if b == 0 else a / b\n\n\ndef evaluate(manifest: dict, findings: list[Finding]) -> dict:\n    expected = []\n    for s in manifest[\"samples\"]:\n        for i, e in enumerate(s[\"expected\"]):\n            expected.append({**e, \"file\": s[\"file\"], \"id\": f\"{s['id']}#{i}\"})\n    scored_files = {s[\"file\"] for s in manifest[\"samples\"]}\n    secure_files = {s[\"file\"] for s in manifest[\"samples\"] if not s[\"expected\"]}\n    scored = [f for f in findings if not f.informational and f.file in scored_files]\n\n    matched_idx: set[int] = set()\n    tp, fn = [], []\n    for e in expected:\n        hits = [(i, f) for i, f in enumerate(scored) if matches(e, f)]\n        if not hits:\n            fn.append(e)\n            continue\n        matched_idx.update(i for i, _ in hits)\n        best = max((f for _, f in hits), key=lambda f: config.SEVERITY_RANK.get(f.severity, 0))\n        tp.append({\"expected\": e, \"tools\": sorted({f.tool for _, f in hits}), \"reported_severity\": best.severity,\n                   \"reported_line\": best.line, \"rules\": sorted({f.rule_id for _, f in hits})})\n\n    fp, unlabeled = [], []\n    for i, f in enumerate(scored):\n        if i in matched_idx:\n            continue  # duplicates of a matched expectation are not false positives\n        (fp if (f.file in secure_files or f.category in config.CATEGORIES) else unlabeled).append(f)\n\n    n_tp, n_fp, n_fn = len(tp), len(fp), len(fn)\n    precision, recall = _div(n_tp, n_tp + n_fp), _div(n_tp, n_tp + n_fn)\n    f1 = None if precision is None or recall is None or (precision + recall) == 0 else 2 * precision * recall / (precision + recall)\n\n    per_cat = defaultdict(lambda: {\"tp\": 0, \"fn\": 0, \"fp\": 0})\n    for t in tp:\n        per_cat[t[\"expected\"][\"category\"]][\"tp\"] += 1\n    for e in fn:\n        per_cat[e[\"category\"]][\"fn\"] += 1\n    for f in fp:\n        per_cat[f.category][\"fp\"] += 1\n    for c, v in per_cat.items():\n        v[\"precision\"], v[\"recall\"] = _div(v[\"tp\"], v[\"tp\"] + v[\"fp\"]), _div(v[\"tp\"], v[\"tp\"] + v[\"fn\"])\n\n    per_tool = defaultdict(lambda: {\"tp\": 0, \"fp\": 0})\n    for t in tp:\n        for tool in t[\"tools\"]:\n            per_tool[tool][\"tp\"] += 1\n    for f in fp:\n        per_tool[f.tool][\"fp\"] += 1\n\n    sev_exact = sum(t[\"expected\"][\"severity\"] == t[\"reported_severity\"] for t in tp)\n    sev_close = sum(abs(config.SEVERITY_RANK[t[\"expected\"][\"severity\"]] - config.SEVERITY_RANK[t[\"reported_severity\"]]) <= 1 for t in tp)\n    line_exact = sum(t[\"expected\"].get(\"line\") == t[\"reported_line\"] for t in tp if t[\"expected\"].get(\"line\") is not None)\n    line_total = sum(1 for t in tp if t[\"expected\"].get(\"line\") is not None)\n\n    return {\n        \"totals\": {\n            \"samples\": len(manifest[\"samples\"]),\n            \"vulnerable_samples\": sum(1 for s in manifest[\"samples\"] if s[\"expected\"]),\n            \"secure_samples\": len(secure_files),\n            \"expected_vulnerabilities\": len(expected),\n            \"secure_samples_with_findings\": len({f.file for f in fp if f.file in secure_files}),\n            \"informational_findings_excluded\": sum(1 for f in findings if f.informational),\n        },\n        \"true_positives\": n_tp, \"false_positives\": n_fp, \"false_negatives\": n_fn,\n        \"precision\": precision, \"recall\": recall, \"f1\": f1,\n        \"severity_exact_match\": _div(sev_exact, n_tp), \"severity_within_one_level\": _div(sev_close, n_tp),\n        \"line_exact_match\": _div(line_exact, line_total),\n        \"per_category\": dict(per_cat), \"per_tool\": dict(per_tool),\n        \"tp_details\": tp,\n        \"fn_details\": fn,\n        \"fp_details\": [f.__dict__ for f in fp],\n        \"unlabeled_findings\": [f.__dict__ for f in unlabeled],\n    }\n",
 "security_eval/models.py": "from __future__ import annotations\n\nfrom dataclasses import dataclass, field\n\n\n@dataclass(frozen=True)\nclass Finding:\n    file: str\n    line: int\n    end_line: int\n    category: str\n    severity: str\n    tool: str\n    rule_id: str\n    message: str = \"\"\n    informational: bool = False\n\n\n@dataclass\nclass ToolRun:\n    tool: str\n    status: str  # ok | timeout | unavailable | error | not_implemented\n    seconds: float = 0.0\n    version: str = \"\"\n    error: str = \"\"\n    finding_count: int = 0\n    parse_errors: int = 0\n\n\n@dataclass\nclass ScanResult:\n    findings: list[Finding] = field(default_factory=list)\n    runs: list[ToolRun] = field(default_factory=list)\n\n    @property\n    def complete(self) -> bool:\n        return all(r.status == \"ok\" for r in self.runs)\n\n    @property\n    def seconds(self) -> float:\n        return sum(r.seconds for r in self.runs)\n",
 "security_eval/normalize.py": "\"\"\"Map raw Bandit / Semgrep output to the unified Finding model.\"\"\"\nfrom __future__ import annotations\n\nimport re\nfrom pathlib import Path\n\nfrom . import config\nfrom .models import Finding\n\nBANDIT_CATEGORY = {\n    \"B608\": \"sql_injection\",\n    \"B602\": \"command_injection\", \"B604\": \"command_injection\",\n    \"B605\": \"command_injection\", \"B609\": \"command_injection\",\n    \"B105\": \"hardcoded_credentials\", \"B106\": \"hardcoded_credentials\", \"B107\": \"hardcoded_credentials\",\n    \"B324\": \"weak_crypto\", \"B303\": \"weak_crypto\", \"B304\": \"weak_crypto\", \"B305\": \"weak_crypto\",\n    \"B301\": \"insecure_deserialization\", \"B302\": \"insecure_deserialization\", \"B506\": \"insecure_deserialization\",\n    \"B701\": \"xss\", \"B702\": \"xss\", \"B703\": \"xss\", \"B704\": \"xss\",\n}\n# Import-presence checks (B401-B415) and low-signal rules are excluded from scoring.\nINFORMATIONAL_BANDIT = {\"B101\", \"B603\", \"B607\"}\n\n\ndef bandit_informational(test_id: str) -> bool:\n    return test_id in INFORMATIONAL_BANDIT or bool(re.fullmatch(r\"B4(0[1-9]|1[0-5])\", test_id))\n\n\ndef bandit_severity(raw: str, category: str) -> str:\n    base = {\"HIGH\": \"High\", \"MEDIUM\": \"Medium\", \"LOW\": \"Low\"}.get(raw.upper(), \"Low\")\n    if base == \"High\" and category in config.CRITICAL_ELIGIBLE:\n        return \"Critical\"\n    return base\n\n\ndef _rel(path: str, root: Path) -> str:\n    try:\n        return Path(path).resolve().relative_to(root.resolve()).as_posix()\n    except ValueError:\n        return Path(path).as_posix()\n\n\ndef from_bandit(item: dict, root: Path) -> Finding:\n    test_id = item.get(\"test_id\", \"\")\n    category = BANDIT_CATEGORY.get(test_id, \"other\")\n    line = int(item.get(\"line_number\", 0))\n    rng = item.get(\"line_range\") or [line]\n    return Finding(\n        file=_rel(item[\"filename\"], root), line=line, end_line=int(max(rng)),\n        category=category, severity=bandit_severity(item.get(\"issue_severity\", \"LOW\"), category),\n        tool=\"bandit\", rule_id=test_id, message=item.get(\"issue_text\", \"\"),\n        informational=bandit_informational(test_id),\n    )\n\n\ndef from_semgrep(item: dict, root: Path) -> Finding:\n    meta = (item.get(\"extra\") or {}).get(\"metadata\") or {}\n    sev = meta.get(\"severity\") or {\"ERROR\": \"High\", \"WARNING\": \"Medium\", \"INFO\": \"Low\"}.get(\n        (item.get(\"extra\") or {}).get(\"severity\", \"INFO\"), \"Low\")\n    return Finding(\n        file=_rel(item[\"path\"], root), line=int(item[\"start\"][\"line\"]), end_line=int(item[\"end\"][\"line\"]),\n        category=meta.get(\"category\", \"other\"), severity=sev, tool=\"semgrep\",\n        rule_id=item[\"check_id\"].rsplit(\".\", 1)[-1], message=(item.get(\"extra\") or {}).get(\"message\", \"\"),\n    )\n",
 "security_eval/report.py": "\"\"\"Write the JSON + Markdown test report. Every number comes from an actual run.\"\"\"\nfrom __future__ import annotations\n\nimport json\nfrom datetime import datetime, timezone\n\nfrom . import config\nfrom .models import ScanResult\n\n\ndef _pct(x):\n    return \"n/a\" if x is None else f\"{x:.1%}\"\n\n\ndef write_report(manifest: dict, scan: ScanResult, ev: dict, perf: dict | None = None, out_dir=None) -> tuple:\n    out_dir = out_dir or config.RESULTS_DIR\n    out_dir.mkdir(parents=True, exist_ok=True)\n    stamp = datetime.now(timezone.utc).isoformat(timespec=\"seconds\")\n    payload = {\n        \"generated_at\": stamp, \"line_tolerance\": config.LINE_TOLERANCE, \"scan_complete\": scan.complete,\n        \"tool_runs\": [r.__dict__ for r in scan.runs], \"evaluation\": ev, \"performance\": perf or {},\n    }\n    (out_dir / \"report.json\").write_text(json.dumps(payload, indent=2, default=str), encoding=\"utf-8\")\n\n    t = ev[\"totals\"]\n    L = [f\"# Security Detection Test Report\", \"\", f\"Generated: {stamp}\", \"\"]\n    if not scan.complete:\n        L += [\"> **WARNING: one or more scanners did not complete. Metrics below are INCOMPLETE.**\", \"\"]\n    L += [\"## Scanner runs\", \"\", \"| Tool | Status | Version | Seconds | Findings | Parse errors |\", \"|---|---|---|---|---|---|\"]\n    for r in scan.runs:\n        L.append(f\"| {r.tool} | {r.status}{' – ' + r.error if r.error else ''} | {r.version} | {r.seconds:.2f} | {r.finding_count} | {r.parse_errors} |\")\n    L += [\"\", \"## Summary\", \"\",\n          f\"- Samples: {t['samples']} ({t['vulnerable_samples']} vulnerable, {t['secure_samples']} secure)\",\n          f\"- Labeled vulnerabilities (ground truth): {t['expected_vulnerabilities']}\",\n          f\"- Correctly detected (TP): {ev['true_positives']}\",\n          f\"- False positives (FP): {ev['false_positives']}\",\n          f\"- False negatives (FN, missed): {ev['false_negatives']}\",\n          f\"- Precision: {_pct(ev['precision'])}  |  Recall: {_pct(ev['recall'])}  |  F1: {_pct(ev['f1'])}\",\n          f\"- Severity exact / within one level (of TPs): {_pct(ev['severity_exact_match'])} / {_pct(ev['severity_within_one_level'])}\",\n          f\"- Line exact match (of TPs): {_pct(ev['line_exact_match'])} (tolerance ±{config.LINE_TOLERANCE})\",\n          f\"- Secure samples with at least one false positive: {t['secure_samples_with_findings']}/{t['secure_samples']}\",\n          f\"- Total scan time: {scan.seconds:.2f}s\"]\n    L += [\"\", \"## Per category\", \"\", \"| Category | TP | FN | FP | Precision | Recall |\", \"|---|---|---|---|---|---|\"]\n    for c in config.CATEGORIES:\n        v = ev[\"per_category\"].get(c, {\"tp\": 0, \"fn\": 0, \"fp\": 0, \"precision\": None, \"recall\": None})\n        L.append(f\"| {c} | {v['tp']} | {v['fn']} | {v['fp']} | {_pct(v.get('precision'))} | {_pct(v.get('recall'))} |\")\n    L += [\"\", \"## Per tool (contribution)\", \"\", \"| Tool | TP found | FP raised |\", \"|---|---|---|\"]\n    for tool, v in sorted(ev[\"per_tool\"].items()):\n        L.append(f\"| {tool} | {v['tp']} | {v['fp']} |\")\n    L += [\"\", \"## Missed vulnerabilities (false negatives)\", \"\"]\n    L += [f\"- `{e['file']}:{e['line']}` {e['category']} ({e['severity']})\" for e in ev[\"fn_details\"]] or [\"- none\"]\n    L += [\"\", \"## False positives\", \"\"]\n    L += [f\"- `{f['file']}:{f['line']}` {f['tool']}/{f['rule_id']} → {f['category']}\" for f in ev[\"fp_details\"]] or [\"- none\"]\n    L += [\"\", \"## Unlabeled findings (not in ground truth; need triage, not counted as FP)\", \"\"]\n    L += [f\"- `{f['file']}:{f['line']}` {f['tool']}/{f['rule_id']} → {f['category']}\" for f in ev[\"unlabeled_findings\"]] or [\"- none\"]\n    if perf:\n        L += [\"\", \"## Performance\", \"\", \"| Test | Seconds | Notes |\", \"|---|---|---|\"]\n        for name, v in perf.items():\n            L.append(f\"| {name} | {v.get('seconds', 0):.2f} | {v.get('note', '')} |\")\n    L += [\"\", \"## How to read this\", \"\",\n          \"- Ground truth comes from inline `# VULN[...]` markers; a detection counts when file, category and line (±tolerance) match.\",\n          \"- Duplicate findings for one vulnerability count once. Import-presence rules (Bandit B401–B415, B101, B603, B607) are excluded from scoring.\",\n          \"- Reported severity for a TP is the highest severity among its matching findings.\",\n          \"- The dataset is small and curated; treat the figures as a regression baseline, not a general accuracy claim.\", \"\"]\n    md = out_dir / \"report.md\"\n    md.write_text(\"\\n\".join(L), encoding=\"utf-8\")\n    return out_dir / \"report.json\", md\n",
 "security_eval/requirements-dev.txt": "pytest>=8\nhttpx>=0.27\nbandit>=1.7\nsemgrep>=1.80\nhindsight-client\npyyaml\nflask\n",
 "security_eval/rules/semgrep/python-security.yml": "rules:\n  - id: sqli-string-built-query\n    languages: [python]\n    severity: ERROR\n    message: SQL query built by string concatenation/formatting and passed to execute(); use parameterized queries.\n    metadata: {category: sql_injection, severity: Critical, cwe: CWE-89}\n    patterns:\n      - pattern-either:\n          - pattern: $C.execute(f\"...{...}...\", ...)\n          - pattern: $C.execute($X + $Y, ...)\n          - pattern: $C.execute($X % $Y, ...)\n          - pattern: $C.execute($X.format(...), ...)\n      - pattern-not: $C.execute(\"...\" + \"...\", ...)\n\n  - id: xss-html-fstring-return\n    languages: [python]\n    severity: ERROR\n    message: HTML response built with an f-string that interpolates values without escaping.\n    metadata: {category: xss, severity: High, cwe: CWE-79}\n    pattern-regex: 'return\\s+f[\"'']<[^\"'']*\\{[^}]+\\}'\n\n  - id: xss-unescaped-dynamic-markup\n    languages: [python]\n    severity: ERROR\n    message: Dynamic content passed to a template/markup sink that disables escaping.\n    metadata: {category: xss, severity: High, cwe: CWE-79}\n    patterns:\n      - pattern-either:\n          - pattern: render_template_string($T, ...)\n          - pattern: Markup($T)\n          - pattern: mark_safe($T)\n      - pattern-not: render_template_string(\"...\", ...)\n      - pattern-not: Markup(\"...\")\n      - pattern-not: mark_safe(\"...\")\n\n  - id: cmdi-os-system-dynamic\n    languages: [python]\n    severity: ERROR\n    message: Shell command built from a non-literal string.\n    metadata: {category: command_injection, severity: Critical, cwe: CWE-78}\n    patterns:\n      - pattern-either:\n          - pattern: os.system($X)\n          - pattern: os.popen($X)\n      - pattern-not: os.system(\"...\")\n      - pattern-not: os.popen(\"...\")\n\n  - id: cmdi-subprocess-shell-dynamic\n    languages: [python]\n    severity: ERROR\n    message: subprocess called with shell=True and a non-literal command.\n    metadata: {category: command_injection, severity: Critical, cwe: CWE-78}\n    patterns:\n      - pattern: subprocess.$F($CMD, ..., shell=True, ...)\n      - pattern-not: subprocess.$F(\"...\", ..., shell=True, ...)\n\n  - id: hardcoded-secret-assignment\n    languages: [python]\n    severity: ERROR\n    message: Credential-like name assigned a string literal; load secrets from the environment or a vault.\n    metadata: {category: hardcoded_credentials, severity: High, cwe: CWE-798}\n    pattern-regex: '(?i)\\b[a-z_]*(api[_-]?key|secret[_-]?key|access[_-]?key|auth[_-]?token|private[_-]?key|passwd|password)[a-z_]*\\s*=\\s*[\"''][^\"'']{6,}[\"'']'\n\n  - id: hardcoded-aws-access-key\n    languages: [python]\n    severity: ERROR\n    message: String looks like an AWS access key id.\n    metadata: {category: hardcoded_credentials, severity: Critical, cwe: CWE-798}\n    pattern-regex: 'AKIA[0-9A-Z]{16}'\n\n  - id: password-hashed-with-fast-hash\n    languages: [python]\n    severity: ERROR\n    message: Password hashed with a fast, unsalted hash; use scrypt, bcrypt or argon2.\n    metadata: {category: insecure_password_storage, severity: High, cwe: CWE-916}\n    patterns:\n      - pattern-either:\n          - pattern: hashlib.$H($PW.encode(...))\n          - pattern: hashlib.$H($PW)\n      - metavariable-regex:\n          metavariable: $H\n          regex: '^(md5|sha1|sha224|sha256|sha384|sha512)$'\n      - metavariable-regex:\n          metavariable: $PW\n          regex: '(?i).*(pass|pwd).*'\n\n  - id: weak-hash-md5-sha1\n    languages: [python]\n    severity: WARNING\n    message: MD5/SHA-1 are broken for security purposes.\n    metadata: {category: weak_crypto, severity: Medium, cwe: CWE-328}\n    patterns:\n      - pattern-either:\n          - pattern: hashlib.md5(...)\n          - pattern: hashlib.sha1(...)\n      - pattern-not: hashlib.md5(..., usedforsecurity=False, ...)\n      - pattern-not: hashlib.sha1(..., usedforsecurity=False, ...)\n\n  - id: weak-cipher-or-mode\n    languages: [python]\n    severity: ERROR\n    message: Broken cipher or ECB mode.\n    metadata: {category: weak_crypto, severity: High, cwe: CWE-327}\n    pattern-either:\n      - pattern: DES.new(...)\n      - pattern: ARC4.new(...)\n      - pattern: Blowfish.new(...)\n      - pattern: AES.new($K, AES.MODE_ECB, ...)\n\n  - id: path-traversal-request-to-file\n    languages: [python]\n    mode: taint\n    severity: ERROR\n    message: Request data flows into a filesystem sink without sanitization.\n    metadata: {category: path_traversal, severity: High, cwe: CWE-22}\n    pattern-sources:\n      - pattern: request.args.get(...)\n      - pattern: request.args[...]\n      - pattern: request.form.get(...)\n      - pattern: request.form[...]\n    pattern-sinks:\n      - pattern: open(...)\n      - pattern: send_file(...)\n      - pattern: send_from_directory(...)\n    pattern-sanitizers:\n      - pattern: secure_filename(...)\n      - pattern: os.path.basename(...)\n\n  - id: unvalidated-request-to-redirect-or-http\n    languages: [python]\n    mode: taint\n    severity: WARNING\n    message: Request data reaches a redirect or outbound HTTP call without validation.\n    metadata: {category: missing_input_validation, severity: High, cwe: CWE-20}\n    pattern-sources:\n      - pattern: request.args.get(...)\n      - pattern: request.args[...]\n      - pattern: request.form.get(...)\n      - pattern: request.json[...]\n    pattern-sinks:\n      - pattern: redirect(...)\n      - pattern: requests.get(...)\n      - pattern: requests.post(...)\n    pattern-sanitizers:\n      - pattern: url_for(...)\n      - patterns:\n          - pattern: $F(...)\n          - metavariable-regex:\n              metavariable: $F\n              regex: '^(validate|sanitize|is_safe|check)_.*'\n\n  - id: jwt-signature-not-verified\n    languages: [python]\n    severity: ERROR\n    message: JWT decoded without verifying the signature.\n    metadata: {category: insecure_authentication, severity: Critical, cwe: CWE-347}\n    pattern-either:\n      - pattern: 'jwt.decode(..., options={..., \"verify_signature\": False, ...}, ...)'\n      - pattern: jwt.decode(..., verify=False, ...)\n\n  - id: plaintext-password-comparison\n    languages: [python]\n    severity: ERROR\n    message: Password compared directly; store a salted hash and compare in constant time.\n    metadata: {category: insecure_authentication, severity: High, cwe: CWE-256}\n    pattern-either:\n      - pattern: $U.password == $P\n      - pattern: $P == $U.password\n",
 "security_eval/run_evaluation.py": "\"\"\"CLI: python -m tests.security_eval.run_evaluation [--language python] [--fail-under]\"\"\"\nfrom __future__ import annotations\n\nimport argparse\nimport json\nimport sys\n\nfrom . import build_manifest, config, metrics, report, scanners\n\n\ndef main() -> int:\n    ap = argparse.ArgumentParser(description=__doc__)\n    ap.add_argument(\"--language\", default=\"python\", choices=sorted(config.LANGUAGES))\n    ap.add_argument(\"--timeout\", type=float, default=config.SCANNER_TIMEOUT)\n    ap.add_argument(\"--rebuild-manifest\", action=\"store_true\")\n    ap.add_argument(\"--fail-under\", action=\"store_true\", help=\"exit 1 if precision/recall are below thresholds\")\n    args = ap.parse_args()\n    for stream in (sys.stdout, sys.stderr):\n        if hasattr(stream, \"reconfigure\"):\n            stream.reconfigure(encoding=\"utf-8\", errors=\"replace\")  # Windows consoles default to cp1252\n\n    if args.rebuild_manifest or not config.MANIFEST_PATH.exists():\n        config.MANIFEST_PATH.write_text(json.dumps(build_manifest.build(), indent=2) + \"\\n\")\n    manifest = json.loads(config.MANIFEST_PATH.read_text(encoding=\"utf-8\"))\n    manifest[\"samples\"] = [s for s in manifest[\"samples\"] if s[\"language\"] == args.language]\n\n    scan = scanners.scan_dataset(manifest, args.language, args.timeout)\n    ev = metrics.evaluate(manifest, scan.findings)\n    perf_path = config.RESULTS_DIR / \"performance.json\"\n    perf = json.loads(perf_path.read_text(encoding=\"utf-8\")) if perf_path.exists() else {}\n    js, md = report.write_report(manifest, scan, ev, perf)\n    print(md.read_text(encoding=\"utf-8\"))\n    if not scan.complete:\n        print(\"Scanners incomplete; see report.\", file=sys.stderr)\n        return 2\n    if args.fail_under and ((ev[\"precision\"] or 0) < config.MIN_PRECISION or (ev[\"recall\"] or 0) < config.MIN_RECALL):\n        return 1\n    return 0\n\n\nif __name__ == \"__main__\":\n    raise SystemExit(main())\n",
 "security_eval/scanners.py": "\"\"\"Run Bandit and Semgrep against an isolated copy of the code. Code is never imported or executed.\"\"\"\nfrom __future__ import annotations\n\nimport importlib.util\nimport json\nimport os\nimport shutil\nimport subprocess\nimport sys\nimport tempfile\nimport time\nfrom pathlib import Path\n\nfrom . import config, normalize\nfrom .models import Finding, ScanResult, ToolRun\n\n\nclass ScannerUnavailable(Exception):\n    pass\n\n\nclass ScannerTimeout(Exception):\n    pass\n\n\ndef resolve_command(tool: str) -> list[str] | None:\n    exe = shutil.which(tool)\n    if exe:\n        return [exe]\n    if importlib.util.find_spec(tool):\n        return [sys.executable, \"-m\", tool]\n    return None\n\n\ndef _run(cmd: list[str], timeout: float, cwd: Path) -> subprocess.CompletedProcess:\n    try:\n        return subprocess.run(  # argument list, no shell\n            cmd, capture_output=True, text=True, timeout=timeout, cwd=cwd,\n            stdin=subprocess.DEVNULL, env={**os.environ, \"PYTHONDONTWRITEBYTECODE\": \"1\"},\n        )\n    except subprocess.TimeoutExpired as exc:\n        raise ScannerTimeout(f\"{cmd[0]} exceeded {timeout}s\") from exc\n    except FileNotFoundError as exc:\n        raise ScannerUnavailable(str(exc)) from exc\n\n\ndef _version(tool: str) -> str:\n    \"\"\"Installed package version from metadata (avoids `semgrep --version`, which can block on the network).\"\"\"\n    try:\n        from importlib.metadata import version\n        return f\"{tool} {version(tool)}\"\n    except Exception:\n        return f\"{tool} (version unknown)\"\n\n\ndef run_bandit(root: Path, timeout: float) -> tuple[list[Finding], ToolRun]:\n    base = resolve_command(\"bandit\")\n    if not base:\n        raise ScannerUnavailable(\"bandit is not installed\")\n    proc = _run(base + [\"-r\", str(root), \"-f\", \"json\", \"-q\"], timeout, root)\n    if proc.returncode not in (0, 1) or not proc.stdout.strip():\n        raise RuntimeError(f\"bandit failed (exit {proc.returncode}): {proc.stderr[:300]}\")\n    data = json.loads(proc.stdout)\n    findings = [normalize.from_bandit(r, root) for r in data.get(\"results\", [])]\n    run = ToolRun(\"bandit\", \"ok\", version=_version(\"bandit\"), parse_errors=len(data.get(\"errors\", [])))\n    return findings, run\n\n\ndef run_semgrep(root: Path, timeout: float) -> tuple[list[Finding], ToolRun]:\n    base = resolve_command(\"semgrep\")\n    if not base:\n        raise ScannerUnavailable(\"semgrep is not installed\")\n    cmd = base + [\"--config\", str(config.RULES_DIR), \"--json\", \"--quiet\", \"--metrics=off\",\n                  \"--disable-version-check\", str(root)]\n    proc = _run(cmd, timeout, root)\n    if proc.returncode not in (0, 1) or not proc.stdout.strip():\n        raise RuntimeError(f\"semgrep failed (exit {proc.returncode}): {proc.stderr[:300]}\")\n    data = json.loads(proc.stdout)\n    findings = [normalize.from_semgrep(r, root) for r in data.get(\"results\", [])]\n    run = ToolRun(\"semgrep\", \"ok\", version=_version(\"semgrep\"), parse_errors=len(data.get(\"errors\", [])))\n    return findings, run\n\n\nRUNNERS = {\"bandit\": run_bandit, \"semgrep\": run_semgrep}\n\n\ndef scan_tree(root: Path, language: str = \"python\", timeout: float | None = None) -> ScanResult:\n    \"\"\"Scan a directory. Never raises for scanner problems: failures are recorded per tool,\n    so a missing or timed-out scanner can never look like 'zero findings'.\"\"\"\n    timeout = config.SCANNER_TIMEOUT if timeout is None else timeout\n    result = ScanResult()\n    for tool in config.LANGUAGES[language][\"scanners\"]:\n        if tool not in RUNNERS:\n            result.runs.append(ToolRun(tool, \"not_implemented\", error=\"scanner adapter not implemented yet\"))\n            continue\n        start = time.perf_counter()\n        try:\n            findings, run = RUNNERS[tool](root, timeout)\n            run.finding_count = len(findings)\n            result.findings.extend(findings)\n        except ScannerTimeout as exc:\n            run = ToolRun(tool, \"timeout\", error=str(exc))\n        except ScannerUnavailable as exc:\n            run = ToolRun(tool, \"unavailable\", error=str(exc))\n        except Exception as exc:  # malformed output, crash, etc.\n            run = ToolRun(tool, \"error\", error=f\"{type(exc).__name__}: {exc}\")\n        run.seconds = time.perf_counter() - start\n        result.runs.append(run)\n    return result\n\n\ndef scan_dataset(manifest: dict, language: str = \"python\", timeout: float | None = None) -> ScanResult:\n    \"\"\"Copy the manifest's files into an isolated temp dir (preserving relative paths) and scan it.\"\"\"\n    with tempfile.TemporaryDirectory(prefix=\"sec_eval_\") as tmp:\n        tmp_root = Path(tmp)\n        for sample in manifest[\"samples\"]:\n            if sample[\"language\"] != language:\n                continue\n            dest = tmp_root / sample[\"file\"]\n            dest.parent.mkdir(parents=True, exist_ok=True)\n            shutil.copyfile(config.DATASET_DIR / sample[\"file\"], dest)\n        return scan_tree(tmp_root, language, timeout)\n",
 "security_eval/test_ai_layer.py": "\"\"\"AI explanation and fix verification against REAL scanner findings.\n\nContract tests run with any provider (including the mock). Quality tests (re-scanning the suggested fix)\nneed a real provider: export EVAL_AI_LIVE=1. Requires app.services.ai.factory:get_provider (override via EVAL_AI_FACTORY).\n\"\"\"\nfrom __future__ import annotations\n\nimport ast\nimport asyncio\nimport inspect\nimport os\nimport shutil\nimport tempfile\nfrom pathlib import Path\n\nimport pytest\n\nfrom tests.security_eval import app_adapter as A\nfrom tests.security_eval import config, scanners\n\nKEYWORDS = {\n    \"sql_injection\": (\"sql\", \"inject\", \"parameter\"), \"xss\": (\"xss\", \"script\", \"escap\"),\n    \"command_injection\": (\"command\", \"shell\", \"inject\"), \"hardcoded_credentials\": (\"hardcoded\", \"secret\", \"credential\", \"environment\"),\n    \"insecure_password_storage\": (\"password\", \"hash\", \"salt\"), \"weak_crypto\": (\"weak\", \"md5\", \"sha\", \"des\", \"crypt\"),\n    \"path_traversal\": (\"path\", \"traversal\", \"directory\"), \"insecure_deserialization\": (\"deserial\", \"pickle\", \"yaml\", \"untrusted\"),\n    \"missing_input_validation\": (\"validat\", \"input\", \"redirect\", \"ssrf\"), \"insecure_authentication\": (\"auth\", \"password\", \"token\", \"signature\"),\n}\n\n\n@pytest.fixture(scope=\"module\")\ndef provider():\n    try:\n        return A.load(A.AI_PROVIDER_FACTORY)()\n    except Exception as exc:  # ImportError, misconfiguration\n        pytest.skip(f\"AI provider factory unavailable: {exc}\")\n\n\ndef _call(fn, *a):\n    out = fn(*a)\n    return asyncio.run(out) if inspect.isawaitable(out) else out\n\n\ndef _text(x):\n    return x if isinstance(x, str) else getattr(x, \"text\", None) or getattr(x, \"code\", None) or str(x)\n\n\n@pytest.fixture(scope=\"module\")\ndef cases(scan_result):\n    seen, out = set(), []\n    for f in scan_result.findings:\n        if f.informational or f.category not in config.CATEGORIES or f.category in seen:\n            continue\n        if not f.file.startswith(\"python/vulnerable/\"):\n            continue\n        seen.add(f.category)\n        code = (config.DATASET_DIR / f.file).read_text(encoding=\"utf-8\")\n        out.append({\"file\": f.file, \"line_start\": f.line, \"line_end\": f.end_line, \"category\": f.category,\n                    \"severity\": f.severity, \"tool\": f.tool, \"rule_id\": f.rule_id, \"message\": f.message, \"snippet\": code})\n    return out\n\n\ndef test_explanations_are_present_and_on_topic(provider, cases):\n    for c in cases:\n        text = _text(_call(provider.explain, c)).strip()\n        assert len(text) > 40, f\"explanation too short for {c['category']}\"\n        if os.getenv(\"EVAL_AI_LIVE\") == \"1\":\n            assert any(k in text.lower() for k in KEYWORDS[c[\"category\"]]), f\"off-topic explanation for {c['category']}\"\n\n\ndef test_fixes_are_valid_python_and_differ(provider, cases):\n    for c in cases:\n        fixed = _text(_call(provider.suggest_fix, c))\n        assert fixed.strip() and fixed.strip() != c[\"snippet\"].strip(), f\"no change proposed for {c['category']}\"\n        ast.parse(fixed)\n\n\n@pytest.mark.skipif(os.getenv(\"EVAL_AI_LIVE\") != \"1\", reason=\"set EVAL_AI_LIVE=1 with a real provider\")\ndef test_fix_removes_the_finding_when_rescanned(provider, cases):\n    for c in cases:\n        fixed = _text(_call(provider.suggest_fix, c))\n        with tempfile.TemporaryDirectory() as tmp:\n            (Path(tmp) / \"fixed.py\").write_text(fixed)\n            res = scanners.scan_tree(Path(tmp))\n        assert res.complete\n        remaining = [f for f in res.findings if not f.informational and f.category in config.ACCEPTED_CATEGORIES[c[\"category\"]]]\n        assert not remaining, f\"suggested fix still flagged for {c['category']}: {[(f.tool, f.rule_id) for f in remaining]}\"\n",
 "security_eval/test_api_integration.py": "\"\"\"End-to-end API tests. Skipped unless EVAL_APP_IMPORT or EVAL_API_URL is set (see app_adapter.py).\"\"\"\nfrom __future__ import annotations\n\nfrom pathlib import Path\n\nimport pytest\n\nfrom tests.security_eval import app_adapter as A\nfrom tests.security_eval import config\n\npytestmark = pytest.mark.skipif(not (A.APP_IMPORT or A.API_URL), reason=\"set EVAL_APP_IMPORT or EVAL_API_URL\")\nF = A.FIELDS\n\n\n@pytest.fixture(scope=\"module\")\ndef client():\n    return A.make_client()\n\n\ndef _sample(split, name):\n    return (config.DATASET_DIR / \"python\" / split / name).read_bytes()\n\n\ndef test_vulnerable_upload_returns_real_findings(client, manifest):\n    for s in manifest[\"samples\"]:\n        if not s[\"expected\"]:\n            continue\n        res = A.upload(client, Path(s[\"file\"]).name, _sample(\"vulnerable\", Path(s[\"file\"]).name))\n        assert res.status_code in (200, 201), res.text\n        found = A.findings_of(res)\n        for e in s[\"expected\"]:\n            ok = [f for f in found if f[F[\"category\"]] in config.ACCEPTED_CATEGORIES[e[\"category\"]]\n                  and abs(f[F[\"line\"]] - e[\"line\"]) <= config.LINE_TOLERANCE]\n            assert ok, f\"API missed {e['category']} at {s['file']}:{e['line']}\"\n            assert all(Path(f[F[\"file\"]]).name == Path(s[\"file\"]).name for f in ok)\n            assert all(f[F[\"severity\"]] in config.SEVERITY_RANK for f in ok)\n\n\ndef test_secure_uploads_have_no_findings(client, manifest):\n    for s in manifest[\"samples\"]:\n        if s[\"split\"] == \"secure\":\n            res = A.upload(client, Path(s[\"file\"]).name, _sample(\"secure\", Path(s[\"file\"]).name))\n            assert res.status_code in (200, 201), res.text\n            assert A.findings_of(res) == [], f\"false positives for {s['file']}\"\n\n\n@pytest.mark.parametrize(\"name,content\", [(\"payload.exe\", b\"MZ\\x90\\x00\"), (\"empty.py\", b\"\"), (\"script.php.txt\", b\"<?php ?>\")])\ndef test_invalid_uploads_rejected(client, name, content):\n    assert 400 <= A.upload(client, name, content).status_code < 500\n\n\ndef test_oversized_upload_rejected(client):\n    res = A.upload(client, \"big.py\", b\"x = 1\\n\" * (A.MAX_UPLOAD_BYTES // 6 + 10))\n    assert res.status_code in (400, 413, 422)\n\n\ndef test_hostile_filename_is_not_trusted(client):\n    res = A.upload(client, \"../../etc/cron.d/x.py\", b\"print('hi')\\n\")\n    assert res.status_code < 500\n    if res.status_code < 300:\n        assert \"..\" not in res.text.split(\"findings\")[0]\n\n\ndef test_consecutive_scans_are_stable(client):\n    body = _sample(\"vulnerable\", \"sql_injection.py\")\n    sigs = []\n    for _ in range(5):\n        res = A.upload(client, \"sql_injection.py\", body)\n        assert res.status_code in (200, 201)\n        sigs.append(sorted((f[F[\"line\"]], f[F[\"category\"]]) for f in A.findings_of(res)))\n    assert all(s == sigs[0] for s in sigs) and sigs[0]\n\n\ndef test_ai_outage_does_not_break_scanning(client, monkeypatch):\n    if not A.APP_IMPORT:\n        pytest.skip(\"failure injection needs in-process mode (EVAL_APP_IMPORT)\")\n\n    class Down:\n        def __getattr__(self, name):\n            def boom(*a, **k):\n                raise RuntimeError(\"simulated LLM outage\")\n            return boom\n\n    module, attr = A.AI_PROVIDER_FACTORY.split(\":\")\n    monkeypatch.setattr(__import__(module, fromlist=[attr]), attr, lambda *a, **k: Down())\n    res = A.upload(client, \"sql_injection.py\", _sample(\"vulnerable\", \"sql_injection.py\"))\n    assert res.status_code in (200, 201, 207), res.text\n    assert A.findings_of(res), \"scanner findings must survive an AI outage\"\n",
 "security_eval/test_dataset_integrity.py": "\"\"\"The dataset itself must be consistent, or every metric derived from it is meaningless.\"\"\"\nimport json\n\nfrom tests.security_eval import build_manifest, config\n\n\ndef test_manifest_matches_markers(manifest):\n    assert json.loads(json.dumps(build_manifest.build()))[\"samples\"][: len(manifest[\"samples\"])] is not None\n    for s in manifest[\"samples\"]:\n        lines = (config.DATASET_DIR / s[\"file\"]).read_text(encoding=\"utf-8\").splitlines()\n        for e in s[\"expected\"]:\n            assert \"VULN[\" in lines[e[\"line\"] - 1], f\"{s['file']}:{e['line']} marker moved\"\n            assert e[\"category\"] in config.CATEGORIES\n            assert e[\"severity\"] in config.SEVERITY_RANK\n\n\ndef test_secure_samples_have_no_markers(manifest):\n    for s in manifest[\"samples\"]:\n        if s[\"split\"] == \"secure\":\n            assert not s[\"expected\"]\n            assert \"VULN[\" not in (config.DATASET_DIR / s[\"file\"]).read_text(encoding=\"utf-8\")\n\n\ndef test_every_category_has_vulnerable_and_secure_sample(manifest):\n    for cat in config.CATEGORIES:\n        vuln = [s for s in manifest[\"samples\"] if any(e[\"category\"] == cat for e in s[\"expected\"])]\n        secure = [s for s in manifest[\"samples\"] if s[\"split\"] == \"secure\" and cat in s[\"file\"]]\n        assert vuln, f\"no vulnerable sample for {cat}\"\n        assert secure, f\"no secure counterpart for {cat}\"\n\n\ndef test_samples_are_valid_python(manifest):\n    import ast\n    for s in manifest[\"samples\"]:\n        ast.parse((config.DATASET_DIR / s[\"file\"]).read_text(encoding=\"utf-8\"))  # parsed, never executed\n",
 "security_eval/test_false_positives.py": "\"\"\"Secure implementations must not be flagged.\"\"\"\nimport json\n\nimport pytest\n\nfrom tests.security_eval import config\n\n_M = json.loads(config.MANIFEST_PATH.read_text(encoding=\"utf-8\")) if config.MANIFEST_PATH.exists() else {\"samples\": []}\nSECURE = [s[\"file\"] for s in _M[\"samples\"] if s[\"language\"] == \"python\" and s[\"split\"] == \"secure\"]\n\n\n@pytest.mark.parametrize(\"path\", SECURE)\ndef test_secure_file_has_no_findings(path, scan_result):\n    bad = [f for f in scan_result.findings if f.file == path and not f.informational]\n    assert not bad, f\"false positives in {path}: \" + \", \".join(f\"{f.tool}/{f.rule_id}@{f.line}\" for f in bad)\n\n\ndef test_no_false_positives_in_vulnerable_files(evaluation):\n    assert evaluation[\"false_positives\"] == 0, evaluation[\"fp_details\"]\n",
 "security_eval/test_hindsight.py": "\"\"\"Hindsight memory tests. Skipped unless HINDSIGHT_URL is set.\n\nASSUMPTION TO VERIFY: the `hindsight-client` package exposes Hindsight(base_url=...).retain(bank_id=, content=) and\n.recall(bank_id=, query=). If your installed version differs, edit ONLY the three helpers below.\nServer restart persistence: set EVAL_HINDSIGHT_RESTART_CMD (e.g. \"docker restart hindsight\").\n\"\"\"\nfrom __future__ import annotations\n\nimport os\nimport subprocess\nimport sys\nimport time\nimport uuid\n\nimport pytest\n\nfrom tests.security_eval import app_adapter as A\nfrom tests.security_eval import config\n\npytestmark = pytest.mark.skipif(not A.HINDSIGHT_URL, reason=\"set HINDSIGHT_URL\")\nBANK = f\"security-eval-{uuid.uuid4().hex[:8]}\"\n\n\ndef _client(url=None):\n    from hindsight_client import Hindsight\n    return Hindsight(base_url=url or A.HINDSIGHT_URL)\n\n\ndef _retain(c, content):\n    return c.retain(bank_id=BANK, content=content)\n\n\ndef _recall(c, query):\n    resp = c.recall(bank_id=BANK, query=query)\n    items = getattr(resp, \"results\", resp)\n    return [getattr(i, \"text\", None) or str(i) for i in items]\n\n\ndef _eventually(fn, pred, timeout=60):\n    end, last = time.time() + timeout, None\n    while time.time() < end:\n        last = fn()\n        if pred(last):\n            return last\n        time.sleep(2)\n    return last\n\n\ndef test_memory_is_stored_and_retrievable():\n    token = f\"tok-{uuid.uuid4().hex[:8]}\"\n    c = _client()\n    _retain(c, f\"Review {token}: SQL injection in get_user(), string concatenation in cursor.execute; fixed with parameterized query.\")\n    got = _eventually(lambda: _recall(c, f\"previous review {token} SQL injection\"), lambda r: any(token in t for t in r))\n    assert any(token in t for t in got), \"stored memory was not retrievable\"\n\n\ndef test_similar_code_pattern_retrieves_relevant_memory_first():\n    token = f\"sqli-{uuid.uuid4().hex[:8]}\"\n    c = _client()\n    _retain(c, f\"{token}: Past review flagged cur.execute('SELECT * FROM users WHERE id=' + user_id) as SQL injection; developer switched to placeholders.\")\n    _retain(c, f\"unrelated-{token}: Past review about rendering an HTML banner with Markup() causing reflected XSS.\")\n    q = \"cursor.execute(\\\"DELETE FROM orders WHERE ref='\\\" + ref + \\\"'\\\")  # string-built SQL query\"\n    got = _eventually(lambda: _recall(c, q), lambda r: any(token in t for t in r))\n    idx = [i for i, t in enumerate(got) if t.startswith(token) or token in t and \"unrelated\" not in t]\n    other = [i for i, t in enumerate(got) if f\"unrelated-{token}\" in t]\n    assert idx, \"similar SQL pattern did not retrieve the SQL memory\"\n    if other:\n        assert idx[0] < other[0], \"unrelated XSS memory outranked the SQL memory\"\n\n\ndef test_developer_feedback_influences_future_recommendation(monkeypatch):\n    if not A.APP_IMPORT:\n        pytest.skip(\"needs in-process app (EVAL_APP_IMPORT) to capture what the AI layer receives\")\n    token = f\"fb-{uuid.uuid4().hex[:8]}\"\n    _retain(_client(), f\"Developer feedback {token}: for SQL injection findings we always use the SQLAlchemy text() with bound params, not raw sqlite3.\")\n    time.sleep(5)\n    seen = []\n\n    class Recorder:\n        def __getattr__(self, name):\n            def call(*a, **k):\n                seen.append(f\"{a} {k}\")\n                return \"recorded\"\n            return call\n\n    module, attr = A.AI_PROVIDER_FACTORY.split(\":\")\n    monkeypatch.setattr(__import__(module, fromlist=[attr]), attr, lambda *a, **k: Recorder())\n    client = A.make_client()\n    body = (config.DATASET_DIR / \"python/vulnerable/sql_injection.py\").read_bytes()\n    assert A.upload(client, \"sql_injection.py\", body).status_code in (200, 201)\n    assert any(token in s for s in seen), \"feedback memory never reached the AI layer\"\n\n\ndef test_memory_persists_across_processes_and_server_restart():\n    token = f\"persist-{uuid.uuid4().hex[:8]}\"\n    _retain(_client(), f\"Review {token}: path traversal in download endpoint, fixed with secure_filename.\")\n    _eventually(lambda: _recall(_client(), token), lambda r: any(token in t for t in r))\n    code = (\"import sys; from hindsight_client import Hindsight; \"\n            f\"r=Hindsight(base_url={A.HINDSIGHT_URL!r}).recall(bank_id={BANK!r}, query={token!r}); \"\n            \"items=getattr(r,'results',r); print(' '.join(getattr(i,'text',None) or str(i) for i in items))\")\n    out = subprocess.run([sys.executable, \"-c\", code], capture_output=True, text=True, timeout=120).stdout\n    assert token in out, \"fresh process could not recall stored memory\"\n    restart = os.getenv(\"EVAL_HINDSIGHT_RESTART_CMD\")\n    if not restart:\n        pytest.skip(\"set EVAL_HINDSIGHT_RESTART_CMD to also verify a real server restart\")\n    subprocess.run(restart, shell=True, check=True, timeout=180)  # operator-supplied command from env\n    got = _eventually(lambda: _recall(_client(), token), lambda r: any(token in t for t in r), timeout=120)\n    assert any(token in t for t in got), \"memory lost after Hindsight restart\"\n\n\ndef test_unreachable_hindsight_fails_fast_not_hang():\n    start = time.time()\n    with pytest.raises(Exception):\n        _recall(_client(\"http://127.0.0.1:9\"), \"anything\")\n    assert time.time() - start < 30\n\n\ndef test_app_keeps_scanning_when_hindsight_is_down(monkeypatch):\n    if not A.APP_IMPORT:\n        pytest.skip(\"failure injection needs in-process mode (EVAL_APP_IMPORT)\")\n\n    def down(*a, **k):\n        raise ConnectionError(\"simulated Hindsight outage\")\n\n    module, attr = A.MEMORY_CLIENT_FACTORY.split(\":\")\n    monkeypatch.setattr(__import__(module, fromlist=[attr]), attr, down)\n    body = (config.DATASET_DIR / \"python/vulnerable/sql_injection.py\").read_bytes()\n    res = A.upload(A.make_client(), \"sql_injection.py\", body)\n    assert res.status_code in (200, 201, 207), res.text\n    assert A.findings_of(res), \"scan must still return findings without memory\"\n",
 "security_eval/test_metrics.py": "\"\"\"Unit tests for the metric math (synthetic findings) plus threshold gate on the real run.\"\"\"\nimport pytest\n\nfrom tests.security_eval import config, metrics\nfrom tests.security_eval.models import Finding\n\n\ndef _m(*expected):\n    return {\"samples\": [\n        {\"id\": \"v\", \"file\": \"v.py\", \"split\": \"vulnerable\", \"expected\": list(expected)},\n        {\"id\": \"s\", \"file\": \"s.py\", \"split\": \"secure\", \"expected\": []},\n    ]}\n\n\ndef _f(file=\"v.py\", line=5, cat=\"sql_injection\", sev=\"High\", tool=\"bandit\", info=False):\n    return Finding(file, line, line, cat, sev, tool, \"R1\", \"\", info)\n\n\nE = {\"category\": \"sql_injection\", \"severity\": \"High\", \"line\": 5}\n\n\ndef test_perfect():\n    ev = metrics.evaluate(_m(E), [_f()])\n    assert (ev[\"true_positives\"], ev[\"false_positives\"], ev[\"false_negatives\"]) == (1, 0, 0)\n    assert ev[\"precision\"] == ev[\"recall\"] == ev[\"f1\"] == 1.0\n\n\ndef test_missed_is_false_negative():\n    ev = metrics.evaluate(_m(E), [])\n    assert ev[\"false_negatives\"] == 1 and ev[\"recall\"] == 0.0 and ev[\"precision\"] is None\n\n\ndef test_finding_in_secure_file_is_false_positive():\n    ev = metrics.evaluate(_m(E), [_f(), _f(file=\"s.py\")])\n    assert ev[\"false_positives\"] == 1 and ev[\"precision\"] == 0.5\n\n\ndef test_duplicates_count_once():\n    ev = metrics.evaluate(_m(E), [_f(tool=\"bandit\"), _f(tool=\"semgrep\")])\n    assert ev[\"true_positives\"] == 1 and ev[\"false_positives\"] == 0\n\n\ndef test_line_tolerance():\n    assert metrics.evaluate(_m(E), [_f(line=5 + config.LINE_TOLERANCE)])[\"true_positives\"] == 1\n    assert metrics.evaluate(_m(E), [_f(line=5 + config.LINE_TOLERANCE + 1)])[\"true_positives\"] == 0\n\n\ndef test_wrong_category_is_miss_and_fp():\n    ev = metrics.evaluate(_m(E), [_f(cat=\"xss\")])\n    assert (ev[\"true_positives\"], ev[\"false_positives\"], ev[\"false_negatives\"]) == (0, 1, 1)\n\n\ndef test_informational_excluded():\n    ev = metrics.evaluate(_m(E), [_f(), _f(file=\"s.py\", info=True)])\n    assert ev[\"false_positives\"] == 0 and ev[\"totals\"][\"informational_findings_excluded\"] == 1\n\n\ndef test_f1_formula():\n    ev = metrics.evaluate(_m(E, {**E, \"line\": 20}), [_f(), _f(file=\"s.py\")])\n    p, r = ev[\"precision\"], ev[\"recall\"]\n    assert ev[\"f1\"] == pytest.approx(2 * p * r / (p + r))\n\n\ndef test_real_run_meets_thresholds(evaluation):\n    assert evaluation[\"precision\"] >= config.MIN_PRECISION, evaluation[\"fp_details\"]\n    assert evaluation[\"recall\"] >= config.MIN_RECALL, evaluation[\"fn_details\"]\n",
 "security_eval/test_robustness.py": "\"\"\"Performance, invalid input, timeouts, scanner outages, and 'never execute uploaded code'.\"\"\"\nfrom __future__ import annotations\n\nimport shutil\nimport time\nfrom pathlib import Path\n\nimport pytest\n\nfrom tests.security_eval import config, scanners\n\nVULN = config.DATASET_DIR / \"python\" / \"vulnerable\"\n\n\ndef _stage(tmp_path: Path, *names: str) -> Path:\n    for n in names:\n        shutil.copyfile(VULN / n, tmp_path / n)\n    return tmp_path\n\n\ndef _scored(res, name):\n    return [f for f in res.findings if f.file == name and not f.informational]\n\n\ndef test_small_file(tmp_path, perf):\n    root = _stage(tmp_path, \"sql_injection.py\")\n    start = time.perf_counter()\n    res = scanners.scan_tree(root)\n    perf(\"small_file_scan\", time.perf_counter() - start, \"1 file, ~12 lines\")\n    assert res.complete and any(f.category == \"sql_injection\" for f in _scored(res, \"sql_injection.py\"))\n\n\ndef test_large_file(tmp_path, perf):\n    filler = \"\\n\".join(f\"def helper_{i}(a, b):\\n    total = a + b * {i}\\n    return total\\n\" for i in range(6000))\n    code = filler + \"\\nimport os\\n\\n\\ndef run(arg):\\n    os.system(\\\"echo \\\" + arg)\\n\"\n    (tmp_path / \"large.py\").write_text(code)\n    start = time.perf_counter()\n    res = scanners.scan_tree(tmp_path)\n    elapsed = time.perf_counter() - start\n    perf(\"large_file_scan\", elapsed, f\"{len(code.splitlines())} lines\")\n    assert res.complete and elapsed < config.LARGE_FILE_MAX_SECONDS\n    last = len(code.splitlines())\n    assert any(f.category == \"command_injection\" and abs(f.line - last) <= 1 for f in _scored(res, \"large.py\"))\n\n\ndef test_consecutive_scans_are_consistent(tmp_path, perf):\n    root = _stage(tmp_path, \"sql_injection.py\", \"xss.py\")\n    runs, times = [], []\n    for _ in range(4):\n        start = time.perf_counter()\n        res = scanners.scan_tree(root)\n        times.append(time.perf_counter() - start)\n        assert res.complete\n        runs.append({(f.file, f.line, f.category, f.rule_id) for f in res.findings})\n    perf(\"consecutive_scans_x4\", sum(times) / len(times), f\"mean of 4; min {min(times):.2f}s max {max(times):.2f}s\")\n    assert all(r == runs[0] for r in runs)\n\n\n@pytest.mark.parametrize(\"name,content\", [\n    (\"empty.py\", b\"\"),\n    (\"binary.py\", bytes(range(256)) * 20),\n    (\"syntax_error.py\", b\"def broken(:\\n    pass\\n\"),\n    (\"non_utf8.py\", b\"x = '\\xff\\xfe\\xfa'\\n\"),\n    (\"one_long_line.py\", b\"x = [\" + b\"1,\" * 200000 + b\"]\\n\"),\n])\ndef test_invalid_files_do_not_crash_scanners(tmp_path, name, content):\n    (tmp_path / name).write_bytes(content)\n    res = scanners.scan_tree(tmp_path)  # must not raise\n    assert all(r.status in {\"ok\", \"error\"} for r in res.runs)\n    assert not any(r.status in {\"unavailable\", \"timeout\"} for r in res.runs)\n\n\ndef test_timeout_is_reported_not_swallowed(tmp_path):\n    root = _stage(tmp_path, \"sql_injection.py\")\n    res = scanners.scan_tree(root, timeout=0.001)\n    assert {r.status for r in res.runs} == {\"timeout\"}\n    assert res.findings == [] and res.complete is False\n\n\ndef test_missing_scanner_is_reported(tmp_path, monkeypatch):\n    root = _stage(tmp_path, \"sql_injection.py\")\n    monkeypatch.setattr(scanners, \"resolve_command\", lambda tool: None)\n    res = scanners.scan_tree(root)\n    assert {r.status for r in res.runs} == {\"unavailable\"} and res.complete is False\n\n\ndef test_unimplemented_language_scanner_is_explicit(tmp_path):\n    (tmp_path / \"a.js\").write_text(\"eval(userInput)\\n\")\n    res = scanners.scan_tree(tmp_path, \"javascript\")\n    assert any(r.tool == \"eslint\" and r.status == \"not_implemented\" for r in res.runs)\n\n\ndef test_uploaded_code_is_never_executed(tmp_path):\n    canary = tmp_path / \"CANARY_EXECUTED\"\n    (tmp_path / \"evil.py\").write_text(\n        f\"import os\\nopen({str(canary)!r}, 'w').write('pwned')\\nos.system('echo ' + input())\\n\")\n    scanners.scan_tree(tmp_path)\n    assert not canary.exists(), \"scanner pipeline executed uploaded code!\"\n",
 "security_eval/test_scanner_detection.py": "\"\"\"Each labeled vulnerability must be found by a real scanner run, with correct file, line and severity.\"\"\"\nimport json\n\nimport pytest\n\nfrom tests.security_eval import config, metrics\n\n_M = json.loads(config.MANIFEST_PATH.read_text(encoding=\"utf-8\")) if config.MANIFEST_PATH.exists() else {\"samples\": []}\nEXPECTED = [{**e, \"file\": s[\"file\"], \"sid\": s[\"id\"]} for s in _M[\"samples\"] if s[\"language\"] == \"python\" for e in s[\"expected\"]]\nIDS = [f\"{e['sid']}:{e['line']}:{e['category']}\" for e in EXPECTED]\n\n\n@pytest.mark.parametrize(\"exp\", EXPECTED, ids=IDS)\ndef test_vulnerability_detected(exp, scan_result):\n    \"\"\"Detection: right file, accepted category, line within tolerance.\"\"\"\n    hits = [f for f in scan_result.findings if not f.informational and metrics.matches(exp, f)]\n    assert hits, f\"MISSED {exp['category']} at {exp['file']}:{exp['line']}\"\n\n\n@pytest.mark.parametrize(\"exp\", EXPECTED, ids=IDS)\ndef test_severity_calibration(exp, scan_result):\n    \"\"\"Severity: highest matching severity must be within one level of the labeled severity.\"\"\"\n    hits = [f for f in scan_result.findings if not f.informational and metrics.matches(exp, f)]\n    if not hits:\n        pytest.skip(\"not detected; see test_vulnerability_detected\")\n    best = max(hits, key=lambda f: config.SEVERITY_RANK[f.severity])\n    assert abs(config.SEVERITY_RANK[best.severity] - config.SEVERITY_RANK[exp[\"severity\"]]) <= 1, (\n        f\"reported {best.severity} ({best.tool}/{best.rule_id}) vs labeled {exp['severity']}\")\n\n\ndef test_findings_carry_file_and_line(scan_result):\n    for f in scan_result.findings:\n        assert f.file and f.line >= 1 and f.end_line >= f.line\n        assert f.severity in config.SEVERITY_RANK\n",
 "__init__.py": "",
 "security_eval/dataset/java/.gitkeep": "",
 "security_eval/dataset/javascript/.gitkeep": "",
 "security_eval/results/.gitkeep": ""
}''')

def main():
    force = "--force" in sys.argv
    base = Path("tests")
    written = skipped = 0
    for rel, content in FILES.items():
        dest = base / rel
        if dest.exists() and not force:
            skipped += 1
            continue
        dest.parent.mkdir(parents=True, exist_ok=True)
        dest.write_text(content, encoding="utf-8")
        written += 1
    print(f"Wrote {written} files, skipped {skipped} existing (use --force to overwrite).")
    subprocess.run([sys.executable, "-m", "tests.security_eval.build_manifest"], check=False)
    print("Next:\n  pip install -r tests/security_eval/requirements-dev.txt\n"
          "  python -m tests.security_eval.run_evaluation\n  python -m pytest tests/security_eval -v")

if __name__ == "__main__":
    main()